mapper.update:
UPDATE MATCHES
SET NOTICE = #{notice, jdbcType=CLOB}
WHERE MATCH_ID = #{matchId}

mapper.select:
SELECT p.POST_ID, p.USER_ID, p.CATEGORY_ID, p.TEAM_ID, p.TITLE, p.CONTENT, p.VIEW_COUNT, p.LIKE_COUNT, p.IS_BLIND, p.IS_DELETED, p.CREATED_AT, p.UPDATED_AT, c.CATEGORY_TYPE, u.NICKNAME, t.TEAM_NAME FROM POSTS p LEFT JOIN CATEGORY c ON c.CATEGORY_ID = p.CATEGORY_ID LEFT JOIN USERS u ON u.USER_ID = p.USER_ID LEFT JOIN TEAMS t ON t.TEAM_ID = p.TEAM_ID
AND p.IS_BLIND = #{isBlind}
AND p.IS_DELETED = #{isDeleted}
AND (p.TITLE LIKE '%' || #{keyword} || '%' OR u.NICKNAME LIKE '%' || #{keyword} || '%')
ORDER BY p.POST_ID DESC

mapper.update:
UPDATE POSTS
SET IS_BLIND = #{isBlind}
WHERE POST_ID = #{postId}

mapper.select:
SELECT c.COMMENT_ID, c.POST_ID, c.USER_ID, c.P_COMMENT_ID, c.CONTENT, c.IS_BLIND, c.IS_DELETED, c.CREATED_AT, c.UPDATED_AT, u.NICKNAME FROM COMMENTS c LEFT JOIN USERS u ON u.USER_ID = c.USER_ID
AND c.IS_BLIND = #{isBlind}
AND c.IS_DELETED = #{isDeleted}
AND (DBMS_LOB.SUBSTR(c.CONTENT, 1000, 1) LIKE '%' || #{keyword} || '%' OR u.NICKNAME LIKE '%' || #{keyword} || '%')
ORDER BY c.COMMENT_ID DESC

mapper.update:
UPDATE COMMENTS
SET IS_BLIND = #{isBlind}
WHERE COMMENT_ID = #{commentId}

UPDATE USERS
SET ROLE_CODE = #{roleCode}
WHERE USER_ID = #{userId}

UPDATE USERS
SET POINT = POINT + #{amount}
WHERE USER_ID = #{userId}
